-- Send an invisible straight line through a tile map and report the first wall it hits.
-- raycasting: original MIT-licensed native educational port.
-- Generated by tools/ports/generate.py; edit the specification to preserve parity.
-- Input: [width, height, ox, oy, dx, dy, limit, ...grid]
-- Output: [cell_x, cell_y, ray_parameter] or []
-- Grid DDA; Y wins corner ties. Direction need not have unit length. Solid tiles are nonzero.
-- Precondition: finite, correctly shaped data; integer indices/counts/IDs.
-- See ../PORTS.md for examples, limits, and the shared test fixtures.

-- Count how many numbers are in this list.
local function port_length(a) return #a end
-- Read one number at a zero-based position; stop if that position does not exist.
local function port_get(a,i) assert(i>=0 and i==math.floor(i) and i<#a,"index"); return a[i+1] end
-- Round down to a whole number; minus 0.1 becomes minus 1.
local function port_floor_num(a) return math.floor(a) end
-- Remove a negative sign so a distance or size is not negative.
local function port_abs_num(a) return math.abs(a) end

-- 1. Start the line at a position and choose its direction.
-- 2. Calculate which tile edge the line will cross next.
-- 3. Move into that next tile and check whether it is a wall.
-- 4. Stop at a wall, the map edge, or the step limit. The returned time-like number tells how
-- far along the line the hit occurred.
local function compute(data)
    local w = 0
    local h = 0
    local ox = 0
    local oy = 0
    local dx = 0
    local dy = 0
    local limit = 0
    local x = 0
    local y = 0
    local sx = 0
    local sy = 0
    local tx = 0
    local ty = 0
    local stepx = 0
    local stepy = 0
    local t = 0
    local i = 0
    w = port_get(data, 0)
    h = port_get(data, 1)
    ox = port_get(data, 2)
    oy = port_get(data, 3)
    dx = port_get(data, 4)
    dy = port_get(data, 5)
    limit = port_get(data, 6)
    if ((w < 1) or (h < 1) or (port_length(data) ~= (7 + (w * h))) or ((dx == 0) and (dy == 0))) then
        return {}
    end
    x = port_floor_num(ox)
    y = port_floor_num(oy)
    sx = -(1)
    sy = -(1)
    if (dx > 0) then
        sx = 1
    end
    if (dy > 0) then
        sy = 1
    end
    -- A large sentinel replaces infinity for this bounded educational ray.
    tx = 1e+30
    ty = 1e+30
    stepx = 1e+30
    stepy = 1e+30
    if (dx ~= 0) then
        tx = ((x - ox) / dx)
        if (dx > 0) then
            tx = (((x + 1) - ox) / dx)
        end
        stepx = port_abs_num((1 / dx))
    end
    if (dy ~= 0) then
        ty = ((y - oy) / dy)
        if (dy > 0) then
            ty = (((y + 1) - oy) / dy)
        end
        stepy = port_abs_num((1 / dy))
    end
    t = 0
    i = 0
    while (i < limit) do
        if ((x < 0) or (x >= w) or (y < 0) or (y >= h)) then
            return {}
        end
        if (port_get(data, ((7 + (y * w)) + x)) ~= 0) then
            return {x, y, t}
        end
        if (tx < ty) then
            t = tx
            tx = tx + stepx
            x = x + sx
        else
            t = ty
            ty = ty + stepy
            y = y + sy
        end
        i = i + 1
    end
    return {}
end
return {compute=compute}
